def key_partition(key, n):
    return sum(ord(c) for c in key) % n

def partition_records(keys, n):
    buckets = [[] for _ in range(n)]
    for k in keys:
        buckets[key_partition(k, n)].append(k)
    return [len(b) for b in buckets]

records = ["user_1"] * 6 + ["user_2"] * 1 + ["user_3"] * 1
sizes_plain = partition_records(records, 4)
print("sin salting:", sizes_plain)

salted = []
counter = 0
for k in records:
    if k == "user_1":
        salted.append(f"{k}#{counter % 3}")
        counter += 1
    else:
        salted.append(k)
sizes_salted = partition_records(salted, 4)
print("con salting:", sizes_salted)
